INSERT INTO `kp_quizzes` VALUES
('quiz_c674aa584c591fdc6773906e4f042e05','PHP & Drupal Architecture Assessment','Test your core knowledge on decoupled Drupal, routing, and database abstraction.','batch_19fd7956a9097b60963b1d45d8a35c10','user_mentor_rakesh',15,70,'[{\"points\":50,\"correctAnswer\":0,\"id\":\"q1\",\"question\":\"Which service handles database interactions in Drupal 11?\",\"options\":[\"Database Connection\",\"Entity Query\",\"EntityManager\",\"SQLHandler\"]},{\"points\":50,\"correctAnswer\":1,\"id\":\"q2\",\"question\":\"Which file defines HTTP REST routes in a custom Drupal module?\",\"options\":[\"routes.php\",\"modulename.routing.yml\",\"api.config.json\",\"web.xml\"]}]',1793526862);
INSERT INTO `kp_resources` VALUES
('res_56eee7849ee373facab5923709a19b6f','Getting Started with Drupal 11 Decoupled API','Detailed walkthrough of headless Drupal architecture, JSON endpoints, and React frontend integration.','TECHNICAL_SKILLS','https://www.youtube.com/watch?v=dQw4w9WgXcQ',45,'https://img.youtube.com/vi/UB1O30fR-EE/maxresdefault.jpg',1,'[]',0,'SESSION','batch_19fd7956a9097b60963b1d45d8a35c10','user_mentor_rakesh',1793526713,1793526713,NULL),
('res_jwt_security','REST API Design & Secure JWT Authentication','Industry standards for decoupled REST APIs, stateless JWT tokens, and CORS security.','TECHNICAL_SKILLS','https://www.youtube.com/watch?v=7Q17ubqL29k',2800,NULL,6,NULL,0,'COURSE',NULL,'user_mentor_rakesh',1793539236,1793539236,NULL),
('res_react19_arch','React 19 & Enterprise Component Architecture','Deep dive into React 19 hooks, component boundaries, server actions, and responsive SaaS UI design.','TECHNICAL_SKILLS','https://www.youtube.com/watch?v=bMknfKXIFA8',3600,NULL,8,NULL,1,'COURSE',NULL,'user_mentor_rakesh',1793539236,1793539236,NULL),
